   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弗丽达捡起地面上的本子，轻轻地翻开它：", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="今天和丽塔一起正式开工了，看着从黎苏根安全生还的她，我感觉一度停滞的心又再次开始了跳动。\n丽塔告诉了我她是如何从黎苏根脱困回国的，这让我很惊讶：那个黑斯廷斯家中，居然也有能无视阶级和派阀想法，一心想要拯救这个国家的人吗？", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187_1", 0, 0, 38.5, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="或许，这个国家的气运还没有结束，可以再继续观察一下。\n丽塔，希望你可以让我们的理想继续延伸。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187_1", 0, 0, 38.5, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [43]={next_id=44, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187_1", 0, 0, 38.5, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [44]={next_id=45, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="永不结束的宴席，酒杯碰撞间全是虚伪的颂词。他们称赞我的研究，恭维我的名姓，眼神里却只有算计。\n每一个微笑都像面具，每一句夸奖都绑着锁链。我越来越常想起我们躲在实验室里的那些夜晚。\n至少那时，我能知道我是否偏航。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187_1", 0, 0, 38.5, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [45]={next_id=46, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="今天又一次交涉破裂。我站在露台，望着工厂的方向，突然觉得喘不过气。\n这座城市的光太亮了，亮得遮住了所有星星。\n如果你在，是不是可以一边和我打趣一边骂我天真，然后又默默陪我熬到天亮？", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187_1", 0, 0, 38.5, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
