   [54]={next_id=55, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她注视着着笼罩“泰诺星”和“空天星链”，喃喃自语着。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [55]={next_id=56, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这一切……都是皇女殿下接见了回国以后的我，让我加入晨星党之后开始的。", msg_color="", msg_size=0, talker="弗丽达", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7143", 2, 0, 18.5, 195.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [56]={next_id=57, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="菲谢尔·维特，你到底在这里藏了什么？", msg_color="", msg_size=0, talker="弗丽达", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7143", 2, 0, 18.5, 195.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [57]={next_id=58, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这时，挂在“空天星链”上的铁牌吸引了弗丽达的视线。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [58]={next_id=59, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弗丽达抚摸着这块铁牌，轻轻念出了上面的诗句——", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [59]={next_id=60, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“巨人铸就钢铁的洪流，为寻雾中不存在的王座。”\n“它们浇筑熔炉，崇拜它的暴烈，跪拜它的荣光。”\n“直到野火将身躯燃烧。”", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [60]={next_id=61, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“矮人凿穿岩石的宫殿，为捧半隙迷途的风。”\n“它们剜取飞羽，贪婪它的轻盈，殉葬它的流浪。”\n“却未曾想到自己拥有翅膀。”", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [61]={next_id=62, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="滴滴。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在弗丽达念完的那一刻，信号声响起，铁牌忽然亮起了幽蓝色的光。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="紧接着，以铁牌为起点，“空天星链”的各个节点次第点亮，幽蓝的光路如血脉般贯通整个装置，它如同从长眠中苏醒的机械蜘蛛，缓缓舒展肢体，露出被保护在核心的“泰诺星”。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“泰诺星”苏醒了，光芒自内部透出，清晰的缝合线在表面浮现游走。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="随后，“泰诺星”上的克罗瓦德地块缓缓凹陷下去，从里面探出一个投影灯，将一个熟悉的人影投射出来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这个声纹锁，被设计成只有我的生命体征消失后才会生效。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当你看到这条消息的时候，想必我已彻底被黑暗吞噬，并由你亲手终结了吧，丽塔。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="弗丽达", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7143", 2, 0, 18.5, 195.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弗丽达沉默着凝视故友的投影。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你做到了我未能做到的事……你挫败了十字党的阴谋，甚至战胜了堕落的我。请……务必昂首挺胸。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="接下来，请你务必记住我说的话，事关【雾】整个事件的幕后黑手。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="克罗瓦德虽然是个封闭且保守的国家，但自始至终都没有落下对源晶、虚粒子和修格尔的研究，而这一切的集大成者……就是我们的老师。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="老师……玛莉亚·冯·霍亨索伦夫人？", msg_color="", msg_size=0, talker="弗丽达", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7143", 2, 0, 18.5, 195.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弗丽达露出困惑的神情，她当然知道自己的老师是相当厉害的源晶研究者，但菲谢尔的话显然意有所指。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [75]={next_id=76, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我想你很清楚，无论是你在黎苏根的研究，还是现在我们制作的“维纳斯系统”，其技术的源头都是老师的研究。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但自从你被流放后，我按照老师留下的笔记进行后续研究的推演和追踪，却发现里面藏有猫腻。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [77]={next_id=78, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="信标最初的功能绝不仅仅是为了操控虚粒子的流向，只是如此的话不能解释为什么它可以引导异变体的脑波来实现一定层面的生物诱导。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="菲谢尔的语气变得低沉，她表情凝重，声音里充满了前所未有的恳切与忧虑。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="老师她……恐怕有什么可怕的秘密没有告诉我们，具体是什么我不清楚，但那绝不会导向什么美好的结局。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="听好了，丽塔，我不敢想象你走的这条路会有多么危险，甚至我自己都成为了你的敌人。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_705.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 1, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
